+CASE WHEN p.[Modulo_apilado] IS NULL THEN N''Modulo_apilado|int|N;'' ELSE N''Modulo_apilado|int|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),p.[Modulo_apilado])))+N'':''+CONVERT(nvarchar(max),p.[Modulo_apilado])+N'';'' END
