+CASE WHEN p.[Cobre_fino_Apilado_Real] IS NULL THEN N''Cobre_fino_Apilado_Real|float(53)|N;'' ELSE N''Cobre_fino_Apilado_Real|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Cobre_fino_Apilado_Real],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Cobre_fino_Apilado_Real],3))+N'';'' END
