+CASE WHEN p.[Ley_CuT_Real_srr] IS NULL THEN N''Ley_CuT_Real_srr|float(53)|N;'' ELSE N''Ley_CuT_Real_srr|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Real_srr],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Real_srr],3))+N'';'' END
+CASE WHEN p.[Ley_CuT_Plan_srr] IS NULL THEN N''Ley_CuT_Plan_srr|float(53)|N;'' ELSE N''Ley_CuT_Plan_srr|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Plan_srr],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Plan_srr],3))+N'';'' END AS nvarchar(max)),N'''') WITHIN GROUP(ORDER BY p.Fecha),N'''')))) payload_sha256
 FROM inventar_SpcHidr.Datos_conciliados_of_ver p WHERE p.run_id=@u) h;
  IF @hash<>(SELECT payload_sha256 FROM inventar_SpcHidr.rep_prod_m6_pending_lote WHERE run_id=@u)
    OR (SELECT COUNT(*) FROM inventar_SpcHidr.Datos_conciliados_of_ver WHERE run_id=@u)<>7
   THROW 52871,''Insercion M6 incompleta o payload diferente del registrado.'',1;
  FETCH NEXT FROM lots INTO @u;
 END
 CLOSE lots;DEALLOCATE lots;
END';
EXEC sys.sp_executesql N'CREATE TRIGGER inventar_SpcHidr.tr_rep_m6_pending_lote_immutable ON inventar_SpcHidr.rep_prod_m6_pending_lote AFTER INSERT,UPDATE,DELETE AS
BEGIN SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM deleted) THROW 52872,''Origen y payload del UUID M6 son inmutables.'',1;
 IF EXISTS(SELECT 1 FROM inserted i JOIN inventar_SpcHidr.Datos_conciliados_of_ver v ON v.run_id=i.run_id)
  THROW 52872,''No atribuir origenM6 a UUID historico existente.'',1;
END';
EXEC sys.sp_executesql N'CREATE PROCEDURE inventar_SpcHidr.sp_rep_m6_insert_pending
 @run_id uniqueidentifier,@caso_id int,@modelo_id int,@solver_run_id int,
 @version_reglas int,@payload_json nvarchar(max),@expected_hash binary(32),@usuario nvarchar(128)
AS
BEGIN
 SET NOCOUNT ON;SET XACT_ABORT ON;
 SET ANSI_NULLS ON;SET ANSI_PADDING ON;SET ANSI_WARNINGS ON;SET ARITHABORT ON;
 SET CONCAT_NULL_YIELDS_NULL ON;SET NUMERIC_ROUNDABORT OFF;
 IF DB_NAME()<>N''inventar_SpcHidr'' OR LOWER(CONVERT(nvarchar(128),SERVERPROPERTY(''ServerName'')))<>N''vps-5347319-x''
  THROW 52870,''Solo DEV autorizado.'',1;
 IF ISNULL(TRY_CONVERT(int,SESSION_CONTEXT(N''m6_pending_execute_dev'')),0)<>1
  THROW 52870,''Falta ejecucion DEV explicita de la ruta pendiente.'',1;
 IF @run_id IS NULL OR @caso_id<>10009 OR @caso_id IS NULL OR @modelo_id<>2 OR @modelo_id IS NULL
  OR @solver_run_id<>10082 OR @solver_run_id IS NULL OR @version_reglas<>1 OR @version_reglas IS NULL
  OR @expected_hash IS NULL OR @usuario IS NULL OR LEN(LTRIM(RTRIM(@usuario)))=0
  THROW 52870,''Esta ruta solo admite caso10009/modelo2/run10082/reglas1.'',1;
 IF NOT EXISTS(SELECT 1 FROM sys.triggers WHERE object_id=OBJECT_ID(N''inventar_SpcHidr.tr_rep_m6_pending_versions_guard'') AND is_disabled=0)
  OR ISNULL(HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),OBJECT_DEFINITION(OBJECT_ID(N''inventar_SpcHidr.tr_rep_m6_pending_versions_guard'')))),0x00)<>0xdf5d82c819db0af254b0205f5d01fb8f9eec22f760dc2ead1d4afa0d6ef343b0
  THROW 52870,''Proteccion M6 no instalada o no coincide con version revisada.'',1;
 IF ISJSON(@payload_json)<>1 OR LEFT(LTRIM(@payload_json),1)<>''['' THROW 52870,''Payload debe ser array JSON.'',1;
 IF (SELECT COUNT(*) FROM OPENJSON(@payload_json))<>7 THROW 52870,''Se requieren siete filas.'',1;
 IF EXISTS(SELECT 1 FROM OPENJSON(@payload_json) r WHERE r.type<>5
  OR (SELECT COUNT(*) FROM OPENJSON(r.value))<>48
  OR (SELECT COUNT(DISTINCT [key] COLLATE Latin1_General_100_BIN2) FROM OPENJSON(r.value))<>48)
  THROW 52870,''Cada fila requiere Fecha y47campos unicos.'',1;
 IF EXISTS(SELECT 1 FROM OPENJSON(@payload_json) r CROSS APPLY OPENJSON(r.value) c
  WHERE c.[key] COLLATE Latin1_General_100_BIN2 NOT IN(N''Fecha'',N''Chancado_TMS_Real'',N''Humedad_Turno_A'',N''Humedad_Turno_B'',N''Humedad_promedio_dia'',N''Sal_turno_A'',N''Sal_Turno_B'',N''Sal_promedio_dia'',N''Apilado_TMH_turno_A'',N''Apilado_TMH_turno_B'',N''Apilado_TMH_promedio_dia'',N''Apilado_TMS_Real'',N''Apilado_TMS_Plan'',N''Campana_apilado'',N''Modulo_apilado'',N''Avance_apilado'',N''Ley_CuT_Real'',N''Ley_CuT_Plan'',N''Cobre_fino_Apilado_Real'',N''Cobre_fino_Apilado_Plan'',N''TMS_Rotopala_1_Real'',N''TMS_Rotopala_1_Plan'',N''Campana_reclamo_oxidos'',N''Modulo_reclamo_oxidos'',N''Avance_reclamo_oxidos'',N''TMS_Rotopala_2_Real'',N''TMS_Rotopala_2_Plan'',N''Campana_reclamo_sulfuros'',N''modulo_reclamo_sulfuros'',N''Avance_reclamo_sulfuros'',N''Camiones_TMS_Reclamo_Oxidos'',N''Camiones_TMS_Reclamo_Sulfuros'',N''Movido'',N''Extraido'',N''Camiones_TMS_total'',N''Camiones_TMS_plan'',N''Campana_reclamo_camiones'',N''Modulo_reclamo_camiones'',N''Total_Ripios_Incluye_Camiones_Real'',N''Total_Ripios_Incluye_Camiones_Plan'',N''Produccion_Catodos_Real'',N''Produccion_Catodos_Plan'',N''SRR_TMS_Turno_A'',N''SRR_TMS_Turno_B'',N''SRR_TMS_promedio_dia'',N''SRR_TMS_Plan'',N''Ley_CuT_Real_srr'',N''Ley_CuT_Plan_srr'')
   OR (c.[key] IN(N''Chancado_TMS_Real'',N''Humedad_Turno_A'',N''Humedad_Turno_B'',N''Humedad_promedio_dia'',N''Sal_turno_A'',N''Sal_Turno_B'',N''Sal_promedio_dia'',N''Apilado_TMH_turno_A'',N''Apilado_TMH_turno_B'',N''Apilado_TMH_promedio_dia'',N''Apilado_TMS_Real'',N''Apilado_TMS_Plan'',N''Modulo_apilado'',N''Avance_apilado'',N''Ley_CuT_Real'',N''Ley_CuT_Plan'',N''Cobre_fino_Apilado_Real'',N''Cobre_fino_Apilado_Plan'',N''TMS_Rotopala_1_Real'',N''TMS_Rotopala_1_Plan'',N''Modulo_reclamo_oxidos'',N''Avance_reclamo_oxidos'',N''TMS_Rotopala_2_Real'',N''TMS_Rotopala_2_Plan'',N''modulo_reclamo_sulfuros'',N''Avance_reclamo_sulfuros'',N''Camiones_TMS_Reclamo_Oxidos'',N''Camiones_TMS_Reclamo_Sulfuros'',N''Camiones_TMS_total'',N''Camiones_TMS_plan'',N''Total_Ripios_Incluye_Camiones_Real'',N''Total_Ripios_Incluye_Camiones_Plan'',N''Produccion_Catodos_Real'',N''Produccion_Catodos_Plan'',N''SRR_TMS_Turno_A'',N''SRR_TMS_Turno_B'',N''SRR_TMS_promedio_dia'',N''SRR_TMS_Plan'',N''Ley_CuT_Real_srr'',N''Ley_CuT_Plan_srr'') AND c.type NOT IN(0,2))
   OR (c.[key] IN(N''Modulo_apilado'',N''Modulo_reclamo_oxidos'',N''modulo_reclamo_sulfuros'',N''Camiones_TMS_plan'',N''Produccion_Catodos_Plan'') AND c.type<>0 AND TRY_CONVERT(int,c.value) IS NULL)
   OR (c.[key] IN(N''Campana_apilado'',N''Campana_reclamo_oxidos'',N''Campana_reclamo_sulfuros'',N''Movido'',N''Extraido'',N''Campana_reclamo_camiones'',N''Modulo_reclamo_camiones'') AND (c.type NOT IN(0,1) OR DATALENGTH(c.value)>510))
   OR (c.[key]=''Fecha'' AND (c.type<>1 OR LEN(c.value)<>10 OR TRY_CONVERT(date,c.value,23) IS NULL)))
  THROW 52870,''Nombres/tipos/fechas del contrato47 invalidos.'',1;
 DECLARE @payload TABLE([Fecha] date NULL,
[Chancado_TMS_Real] float(53) NULL,
[Humedad_Turno_A] float(53) NULL,
[Humedad_Turno_B] float(53) NULL,
