[Sal_Turno_B] float(53) NULL,
[Sal_promedio_dia] float(53) NULL,
[Apilado_TMH_turno_A] float(53) NULL,
[Apilado_TMH_turno_B] float(53) NULL,
[Apilado_TMH_promedio_dia] float(53) NULL,
[Apilado_TMS_Real] float(53) NULL,
[Apilado_TMS_Plan] float(53) NULL,
[Campana_apilado] nvarchar(255) NULL,
[Modulo_apilado] int NULL,
[Avance_apilado] float(53) NULL,
[Ley_CuT_Real] float(53) NULL,
[Ley_CuT_Plan] float(53) NULL,
[Cobre_fino_Apilado_Real] float(53) NULL,
[Cobre_fino_Apilado_Plan] float(53) NULL,
[TMS_Rotopala_1_Real] float(53) NULL,
[TMS_Rotopala_1_Plan] float(53) NULL,
[Campana_reclamo_oxidos] nvarchar(255) NULL,
[Modulo_reclamo_oxidos] int NULL,
[Avance_reclamo_oxidos] float(53) NULL,
[TMS_Rotopala_2_Real] float(53) NULL,
[TMS_Rotopala_2_Plan] float(53) NULL,
[Campana_reclamo_sulfuros] nvarchar(255) NULL,
[modulo_reclamo_sulfuros] int NULL,
[Avance_reclamo_sulfuros] float(53) NULL,
[Camiones_TMS_Reclamo_Oxidos] float(53) NULL,
[Camiones_TMS_Reclamo_Sulfuros] float(53) NULL,
[Movido] nvarchar(255) NULL,
[Extraido] nvarchar(255) NULL,
