[Ley_CuT_Plan_srr] float(53) NULL);
 INSERT @payload SELECT * FROM OPENJSON(@payload_json) WITH([Fecha] date ''$.Fecha'',[Chancado_TMS_Real] float(53) ''$.Chancado_TMS_Real'',[Humedad_Turno_A] float(53) ''$.Humedad_Turno_A'',[Humedad_Turno_B] float(53) ''$.Humedad_Turno_B'',[Humedad_promedio_dia] float(53) ''$.Humedad_promedio_dia'',[Sal_turno_A] float(53) ''$.Sal_turno_A'',[Sal_Turno_B] float(53) ''$.Sal_Turno_B'',[Sal_promedio_dia] float(53) ''$.Sal_promedio_dia'',[Apilado_TMH_turno_A] float(53) ''$.Apilado_TMH_turno_A'',[Apilado_TMH_turno_B] float(53) ''$.Apilado_TMH_turno_B'',[Apilado_TMH_promedio_dia] float(53) ''$.Apilado_TMH_promedio_dia'',[Apilado_TMS_Real] float(53) ''$.Apilado_TMS_Real'',[Apilado_TMS_Plan] float(53) ''$.Apilado_TMS_Plan'',[Campana_apilado] nvarchar(255) ''$.Campana_apilado'',[Modulo_apilado] int ''$.Modulo_apilado'',[Avance_apilado] float(53) ''$.Avance_apilado'',[Ley_CuT_Real] float(53) ''$.Ley_CuT_Real'',[Ley_CuT_Plan] float(53) ''$.Ley_CuT_Plan'',[Cobre_fino_Apilado_Real] float(53) ''$.Cobre_fino_Apilado_Real'',[Cobre_fino_Apilado_Plan] float(53) ''$.Cobre_fino_Apilado_Plan'',[TMS_Rotopala_1_Real] float(53) ''$.TMS_Rotopala_1_Real'',[TMS_Rotopala_1_Plan] float(53) ''$.TMS_Rotopala_1_Plan'',[Campana_reclamo_oxidos] nvarchar(255) ''$.Campana_reclamo_oxidos'',[Modulo_reclamo_oxidos] int ''$.Modulo_reclamo_oxidos'',[Avance_reclamo_oxidos] float(53) ''$.Avance_reclamo_oxidos'',[TMS_Rotopala_2_Real] float(53) ''$.TMS_Rotopala_2_Real'',[TMS_Rotopala_2_Plan] float(53) ''$.TMS_Rotopala_2_Plan'',[Campana_reclamo_sulfuros] nvarchar(255) ''$.Campana_reclamo_sulfuros'',[modulo_reclamo_sulfuros] int ''$.modulo_reclamo_sulfuros'',[Avance_reclamo_sulfuros] float(53) ''$.Avance_reclamo_sulfuros'',[Camiones_TMS_Reclamo_Oxidos] float(53) ''$.Camiones_TMS_Reclamo_Oxidos'',[Camiones_TMS_Reclamo_Sulfuros] float(53) ''$.Camiones_TMS_Reclamo_Sulfuros'',[Movido] nvarchar(255) ''$.Movido'',[Extraido] nvarchar(255) ''$.Extraido'',[Camiones_TMS_total] float(53) ''$.Camiones_TMS_total'',[Camiones_TMS_plan] int ''$.Camiones_TMS_plan'',[Campana_reclamo_camiones] nvarchar(255) ''$.Campana_reclamo_camiones'',[Modulo_reclamo_camiones] nvarchar(255) ''$.Modulo_reclamo_camiones'',[Total_Ripios_Incluye_Camiones_Real] float(53) ''$.Total_Ripios_Incluye_Camiones_Real'',[Total_Ripios_Incluye_Camiones_Plan] float(53) ''$.Total_Ripios_Incluye_Camiones_Plan'',[Produccion_Catodos_Real] float(53) ''$.Produccion_Catodos_Real'',[Produccion_Catodos_Plan] int ''$.Produccion_Catodos_Plan'',[SRR_TMS_Turno_A] float(53) ''$.SRR_TMS_Turno_A'',[SRR_TMS_Turno_B] float(53) ''$.SRR_TMS_Turno_B'',[SRR_TMS_promedio_dia] float(53) ''$.SRR_TMS_promedio_dia'',[SRR_TMS_Plan] float(53) ''$.SRR_TMS_Plan'',[Ley_CuT_Real_srr] float(53) ''$.Ley_CuT_Real_srr'',[Ley_CuT_Plan_srr] float(53) ''$.Ley_CuT_Plan_srr'');
 IF (SELECT COUNT(DISTINCT Fecha) FROM @payload)<>7
  OR EXISTS(SELECT 1 FROM @payload WHERE Fecha IS NULL OR Fecha NOT BETWEEN ''20260901'' AND ''20260907'')
  THROW 52870,''Periodo incompleto/duplicado o distinto de01..07Sep2026.'',1;
 DECLARE @hash binary(32);
 SELECT @hash=payload_sha256 FROM (SELECT CONVERT(binary(32),HASHBYTES(''SHA2_256'',CONVERT(varbinary(max),
 CAST(N''M6-PENDING-SET-v1;'' AS nvarchar(max))+CONVERT(nvarchar(20),COUNT_BIG(*))+N'';''+
 COALESCE(STRING_AGG(CAST(CAST(N''M6-PENDING-47-v1;'' AS nvarchar(max))
+CASE WHEN p.[Fecha] IS NULL THEN N''Fecha|date|N;'' ELSE N''Fecha|date|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(char(10),p.[Fecha],23))))+N'':''+CONVERT(nvarchar(max),CONVERT(char(10),p.[Fecha],23))+N'';'' END
+CASE WHEN p.[Chancado_TMS_Real] IS NULL THEN N''Chancado_TMS_Real|float(53)|N;'' ELSE N''Chancado_TMS_Real|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Chancado_TMS_Real],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Chancado_TMS_Real],3))+N'';'' END
+CASE WHEN p.[Humedad_Turno_A] IS NULL THEN N''Humedad_Turno_A|float(53)|N;'' ELSE N''Humedad_Turno_A|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_Turno_A],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_Turno_A],3))+N'';'' END
+CASE WHEN p.[Humedad_Turno_B] IS NULL THEN N''Humedad_Turno_B|float(53)|N;'' ELSE N''Humedad_Turno_B|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_Turno_B],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_Turno_B],3))+N'';'' END
+CASE WHEN p.[Humedad_promedio_dia] IS NULL THEN N''Humedad_promedio_dia|float(53)|N;'' ELSE N''Humedad_promedio_dia|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_promedio_dia],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Humedad_promedio_dia],3))+N'';'' END
+CASE WHEN p.[Sal_turno_A] IS NULL THEN N''Sal_turno_A|float(53)|N;'' ELSE N''Sal_turno_A|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_turno_A],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_turno_A],3))+N'';'' END
+CASE WHEN p.[Sal_Turno_B] IS NULL THEN N''Sal_Turno_B|float(53)|N;'' ELSE N''Sal_Turno_B|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_Turno_B],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_Turno_B],3))+N'';'' END
+CASE WHEN p.[Sal_promedio_dia] IS NULL THEN N''Sal_promedio_dia|float(53)|N;'' ELSE N''Sal_promedio_dia|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_promedio_dia],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Sal_promedio_dia],3))+N'';'' END
+CASE WHEN p.[Apilado_TMH_turno_A] IS NULL THEN N''Apilado_TMH_turno_A|float(53)|N;'' ELSE N''Apilado_TMH_turno_A|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_turno_A],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_turno_A],3))+N'';'' END
+CASE WHEN p.[Apilado_TMH_turno_B] IS NULL THEN N''Apilado_TMH_turno_B|float(53)|N;'' ELSE N''Apilado_TMH_turno_B|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_turno_B],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_turno_B],3))+N'';'' END
+CASE WHEN p.[Apilado_TMH_promedio_dia] IS NULL THEN N''Apilado_TMH_promedio_dia|float(53)|N;'' ELSE N''Apilado_TMH_promedio_dia|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_promedio_dia],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMH_promedio_dia],3))+N'';'' END
+CASE WHEN p.[Apilado_TMS_Real] IS NULL THEN N''Apilado_TMS_Real|float(53)|N;'' ELSE N''Apilado_TMS_Real|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMS_Real],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMS_Real],3))+N'';'' END
+CASE WHEN p.[Apilado_TMS_Plan] IS NULL THEN N''Apilado_TMS_Plan|float(53)|N;'' ELSE N''Apilado_TMS_Plan|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMS_Plan],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Apilado_TMS_Plan],3))+N'';'' END
+CASE WHEN p.[Campana_apilado] IS NULL THEN N''Campana_apilado|nvarchar(255)|N;'' ELSE N''Campana_apilado|nvarchar(255)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),p.[Campana_apilado])))+N'':''+CONVERT(nvarchar(max),p.[Campana_apilado])+N'';'' END
+CASE WHEN p.[Modulo_apilado] IS NULL THEN N''Modulo_apilado|int|N;'' ELSE N''Modulo_apilado|int|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),p.[Modulo_apilado])))+N'':''+CONVERT(nvarchar(max),p.[Modulo_apilado])+N'';'' END
