 FROM inventar_SpcHidr.rep_prod_ajustado_stg p WHERE p.run_id=@run_id) h;
  IF @old_hash<>@hash OR @stage_hash<>@hash OR (SELECT COUNT(*) FROM inventar_SpcHidr.Datos_conciliados_of_ver WHERE run_id=@run_id)<>7
   OR EXISTS(SELECT 1 FROM inventar_SpcHidr.rep_prod_ajustado_stg WHERE run_id=@run_id AND (caso_id<>@caso_id OR version_reglas<>@version_reglas))
