 END
 IF EXISTS(SELECT 1 FROM inventar_SpcHidr.rep_prod_ajustado_stg WITH(UPDLOCK,HOLDLOCK) WHERE run_id=@run_id)
  OR EXISTS(SELECT 1 FROM inventar_SpcHidr.Datos_conciliados_of_ver WITH(UPDLOCK,HOLDLOCK) WHERE run_id=@run_id)
  THROW 52870,''UUID ya utilizado fuera de la ruta M6; no atribuir origen retrospectivo.'',1;
 IF NOT EXISTS(SELECT 1 FROM DEV_SIIR.hidro.recon_caso c WITH(HOLDLOCK)
 JOIN DEV_SIIR.hidro.recon_modelo m WITH(HOLDLOCK) ON m.id=c.modelo_id
 JOIN DEV_SIIR.hidro.recon_solver_run r WITH(HOLDLOCK) ON r.caso_id=c.id AND r.id=@solver_run_id
 WHERE c.id=@caso_id AND c.modelo_id=@modelo_id AND m.codigo=''hidrometalurgia_125_v2''
 AND m.total_flujos=125 AND m.legacy_modelo_id=6 AND m.activo=1 AND r.estado=''success''
 AND CAST(c.fecha_inicio AS date)=''20260901'' AND CAST(c.fecha_fin AS date)=''20260907'')
  THROW 52870,''Caso/modelo/solver/periodo no corresponde.'',1;
 IF (SELECT COUNT(*) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id)<>125
  OR (SELECT COUNT(DISTINCT codigo_flujo) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id)<>125
  THROW 52870,''Resultados125 incompletos/duplicados.'',1;
 IF EXISTS(SELECT 1 FROM DEV_SIIR.hidro.recon_resultado_flujo r WITH(HOLDLOCK)
 LEFT JOIN DEV_SIIR.hidro.recon_flujo_modelo f WITH(HOLDLOCK) ON f.id=r.flujo_modelo_id
 WHERE r.caso_id=@caso_id AND r.run_id=@solver_run_id AND
 (f.modelo_id IS NULL OR f.modelo_id<>@modelo_id OR f.activo<>1 OR f.codigo_flujo<>r.codigo_flujo
 OR TRY_CONVERT(int,SUBSTRING(r.codigo_flujo,2,10)) IS NULL
 OR TRY_CONVERT(int,SUBSTRING(r.codigo_flujo,2,10)) NOT BETWEEN 1 AND 125
 OR r.codigo_flujo<>CONCAT(''F'',TRY_CONVERT(int,SUBSTRING(r.codigo_flujo,2,10)))
 OR r.masa_reconciliada IS NULL OR r.fino_cu_reconciliado IS NULL))
  THROW 52870,''Claves reconciliadas no pertenecen al modelo125.'',1;
 IF EXISTS(SELECT 1 FROM @payload WHERE [Chancado_TMS_Real] IS NULL OR [Chancado_TMS_Real]<0 OR [Sal_turno_A] IS NULL OR [Sal_turno_A]<0 OR [Sal_Turno_B] IS NULL OR [Sal_Turno_B]<0 OR [Sal_promedio_dia] IS NULL OR [Sal_promedio_dia]<0 OR [Apilado_TMH_turno_A] IS NULL OR [Apilado_TMH_turno_A]<0 OR [Apilado_TMH_turno_B] IS NULL OR [Apilado_TMH_turno_B]<0 OR [Apilado_TMH_promedio_dia] IS NULL OR [Apilado_TMH_promedio_dia]<0 OR [Apilado_TMS_Real] IS NULL OR [Apilado_TMS_Real]<0 OR [Ley_CuT_Real] IS NULL OR [Ley_CuT_Real]<0 OR [Cobre_fino_Apilado_Real] IS NULL OR [Cobre_fino_Apilado_Real]<0 OR [TMS_Rotopala_1_Real] IS NULL OR [TMS_Rotopala_1_Real]<0 OR [TMS_Rotopala_2_Real] IS NULL OR [TMS_Rotopala_2_Real]<0 OR [Camiones_TMS_Reclamo_Oxidos] IS NULL OR [Camiones_TMS_Reclamo_Oxidos]<0 OR [Camiones_TMS_Reclamo_Sulfuros] IS NULL OR [Camiones_TMS_Reclamo_Sulfuros]<0 OR [Total_Ripios_Incluye_Camiones_Real] IS NULL OR [Total_Ripios_Incluye_Camiones_Real]<0 OR [SRR_TMS_Turno_A] IS NULL OR [SRR_TMS_Turno_A]<0 OR [SRR_TMS_Turno_B] IS NULL OR [SRR_TMS_Turno_B]<0 OR [SRR_TMS_promedio_dia] IS NULL OR [SRR_TMS_promedio_dia]<0 OR [Ley_CuT_Real_srr] IS NULL OR [Ley_CuT_Real_srr]<0) THROW 52870,''Columnas ajustadas ausentes/negativas.'',1;
 DECLARE @checks TABLE(actual float,target float);
 INSERT @checks VALUES ((SELECT SUM(Chancado_TMS_Real) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F3''))),
((SELECT SUM(Sal_promedio_dia) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F13'',''F14''))),
((SELECT SUM(SRR_TMS_promedio_dia) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F9''))),
((SELECT SUM(SRR_TMS_promedio_dia*Ley_CuT_Real_srr/100.0) FROM @payload),(SELECT SUM(fino_cu_reconciliado) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F9''))),
((SELECT SUM(Apilado_TMS_Real) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F18'',''F19''))),
((SELECT SUM(Cobre_fino_Apilado_Real) FROM @payload),(SELECT SUM(fino_cu_reconciliado) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F18'',''F19''))),
((SELECT SUM(TMS_Rotopala_1_Real) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F32''))),
((SELECT SUM(TMS_Rotopala_2_Real) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F35''))),
((SELECT SUM(Camiones_TMS_Reclamo_Oxidos) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F33''))),
((SELECT SUM(Camiones_TMS_Reclamo_Sulfuros) FROM @payload),(SELECT SUM(masa_reconciliada) FROM DEV_SIIR.hidro.recon_resultado_flujo WITH(HOLDLOCK) WHERE caso_id=@caso_id AND run_id=@solver_run_id AND codigo_flujo IN(''F36'')));
 IF EXISTS(SELECT 1 FROM @checks WHERE actual IS NULL OR target IS NULL OR ABS(actual-target)>1E-8+ABS(target)*1E-12)
  THROW 52870,''Los objetivos reconciliados no coinciden con el payload.'',1;
 IF EXISTS(SELECT 1 FROM @payload WHERE Ley_CuT_Real>100 OR Ley_CuT_Real_srr>100
 OR ABS(Apilado_TMS_Real*Ley_CuT_Real/100.0-Cobre_fino_Apilado_Real)>1E-8+ABS(Cobre_fino_Apilado_Real)*1E-12
 OR ABS(SRR_TMS_Turno_A+SRR_TMS_Turno_B-SRR_TMS_promedio_dia)>1E-8+ABS(SRR_TMS_promedio_dia)*1E-12
 OR ABS(Sal_turno_A+Sal_Turno_B-Sal_promedio_dia)>1E-8+ABS(Sal_promedio_dia)*1E-12
 OR ABS(Apilado_TMH_turno_A+Apilado_TMH_turno_B-Apilado_TMH_promedio_dia)>1E-8+ABS(Apilado_TMH_promedio_dia)*1E-12)
  THROW 52870,''Relaciones diarias incompatibles con reglas vigentes.'',1;
 IF (SELECT COUNT(*) FROM inventar_SpcHidr.Datos_conciliados_of WITH(HOLDLOCK) WHERE Fecha BETWEEN ''20260901'' AND ''20260907'')<>7
  OR EXISTS(SELECT Fecha,[Humedad_Turno_A],[Humedad_Turno_B],[Humedad_promedio_dia],[Apilado_TMS_Plan],[Campana_apilado],[Modulo_apilado],[Avance_apilado],[Ley_CuT_Plan],[Cobre_fino_Apilado_Plan],[TMS_Rotopala_1_Plan],[Campana_reclamo_oxidos],[Modulo_reclamo_oxidos],[Avance_reclamo_oxidos],[TMS_Rotopala_2_Plan],[Campana_reclamo_sulfuros],[modulo_reclamo_sulfuros],[Avance_reclamo_sulfuros],[Movido],[Extraido],[Camiones_TMS_total],[Camiones_TMS_plan],[Campana_reclamo_camiones],[Modulo_reclamo_camiones],[Total_Ripios_Incluye_Camiones_Plan],[Produccion_Catodos_Real],[Produccion_Catodos_Plan],[SRR_TMS_Plan],[Ley_CuT_Plan_srr] FROM @payload EXCEPT
