+CASE WHEN p.[Ley_CuT_Real_srr] IS NULL THEN N''Ley_CuT_Real_srr|float(53)|N;'' ELSE N''Ley_CuT_Real_srr|float(53)|V''+CONVERT(nvarchar(20),DATALENGTH(CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Real_srr],3))))+N'':''+CONVERT(nvarchar(max),CONVERT(varchar(99),p.[Ley_CuT_Real_srr],3))+N'';'' END
